Looking at the qlang documentation and examples, I'll write queries for each task. The language pipelines values through steps, with each step transforming the input.

N1: /data/users | filter ~(/active) | filter ~(at /email | ne null) | * (/email | split "@" | last | lower) | distinct | sort

N2: filter ~(/status | lower | eq "paid") | * {:customer /customer/name :amount ((/lines | * (/qty * /unit_price) | sum | coalesce 0) - (at /discount | coalesce 0))} | groupBy ~/customer | * (. | * /amount | sum) | entries | sort ~((/1 | desc)) | take 2 | * {:customer (/0 | keyword) :total (/1 | round 2)}

N3: filter ~(/state | eq "open") | * (at /assignee/login | coalesce "unassigned") | groupBy | * count

N4: (at /dependencies | coalesce {}) | union (at /devDependencies | coalesce {}) | entries | filter ~(/1 | startsWith "^") | * /0 | sort

N5: /services | filter ~(/enabled | eq true) | {:enabledCount (count) :ports (. | * (at /port) | filter ~(ne null) | distinct | sort) :totalReplicas (. | * (at /replicas | coalesce 1) | sum)}

N6: split "\n" | * (split " " | {:level /1 :service (/2 | split "[" / /1 | split "]" / /0)}) | filter ~(/level | eq "ERROR") | * /service | groupBy | * count | entries | sort ~([(/1 | desc) (/0)]) | take 2 | * {:service (/0 | keyword) :count /1}

N7: lines | drop 1 | * (split ",") | filter ~(and (/2 | ne "") (/3 | ne "")) | * {:region (/0 | lower) :revenue (* (/2 | parseJson) (/3 | parseJson))} | groupBy ~/region | * (. | * /revenue | sum | round 2)

N8: groupBy ~/user | * (:has_login (. | * (/type | lower | eq "login") | any) :has_logout (. | * (/type | lower | eq "logout") | any)) | filter ~(and /has_login (not /has_logout)) | keys | * (keyword) | sort

N9: filter ~(at /salary | ne null) | groupBy ~/dept | * (. | [* /salary | sum (count)] | /0 / /1 | round 1)

N10: lines | filter ~(ne "") | * (split ":" / /1 | split "," | * (lower)) | flat | distinct | sort

N11: ["Apple" "banana" "apple" "Cherry" "BANANA" "apple" "date"] | * (lower) | groupBy | * count | filter ~(gt 1) | entries | sort ~([(/1 | desc) (/0)]) | * {:word (/0 | keyword) :count /1}

N12: /releases | filter ~(and (eq /draft false) (eq /prerelease false)) | * {:tag /tag_name :downloads (at /assets | coalesce [] | * (at /download_count | coalesce 0) | sum)} | sort ~((/downloads | desc)) | take 3 | * {:tag /tag :downloads /downloads}

N13: filter ~(/category | lower | eq "tools") | {:count (count) :allPriced (. | * (/price | if (ne null) (gt 0) false) | every) :inStockNames (. | filter ~(/stock | gt 0) | * /name | sort)}

N14: lines | filter ~(and (ne "") (not (startsWith "#")) (not (startsWith "-"))) | * (split "#" / /0 | if (contains "==") (split "==" | {(/0 | lower): /1}) {}) | reduce {} ~(union)
